/**
 * The explore page module, bound to /themes by its asset key
 * (js/pages/themes/index.js). Search, category, sort and mode live in the URL:
 * read on load and replaced on every change. The named exports are the pure
 * half; the default export wires the page.
 * No framework imports: the pill groups are the shared libs/pills.js.
 */
import { bindPills } from '../../libs/pills.js';

const DEFAULTS = { q: '', category: '', sort: 'featured', mode: 'desktop' };
const SORTS = ['featured', 'az', 'color'];
const MODES = ['desktop', 'phone'];
// Under this much chroma an accent reads as a grey, which has no place in a rainbow
const MIN_CHROMA = 20;

/**
 * The page state a URL search string names, defaults filling every gap.
 * @param {string} search - a URL search string, with or without its `?`
 * @returns {{ q: string, category: string, sort: string, mode: string }}
 */
export function readState(search) {
  const params = new URLSearchParams(search);
  const known = (key, values) => (values.includes(params.get(key)) ? params.get(key) : DEFAULTS[key]);

  return {
    q: params.get('q') ?? DEFAULTS.q,
    category: params.get('category') ?? DEFAULTS.category,
    sort: known('sort', SORTS),
    mode: known('mode', MODES),
  };
}

/**
 * The URL search string for a state, every default left out.
 * @param {object} state - the page state
 * @returns {string} `?key=value&...`, or '' when every value is a default
 */
export function writeState(state) {
  const params = new URLSearchParams();

  for (const key of Object.keys(DEFAULTS)) {
    if (state[key] && state[key] !== DEFAULTS[key]) {
      params.set(key, state[key]);
    }
  }

  const query = params.toString();

  return query ? `?${query}` : '';
}

/**
 * Whether a theme passes the state's category and every word of its search,
 * case-insensitive over the name, business, niche and tags.
 * @param {{ name: string, business: string, niche: string, tags: string[], category: string }} theme
 * @param {object} state - the page state; missing keys read as defaults
 * @returns {boolean}
 */
export function matches(theme, state) {
  const { q, category } = { ...DEFAULTS, ...state };
  const words = q.toLowerCase().split(/\s+/).filter(Boolean);
  const text = [theme.name, theme.business, theme.niche, ...theme.tags].join(' ').toLowerCase();

  return (!category || theme.category === category)
    && words.every((word) => text.includes(word));
}

/**
 * The themes in a sort's order, as a new array: featured keeps the data
 * order (explorer.js sorts it), az sorts by name, color runs the rainbow of
 * the accents from the reds, greys last.
 * @param {object[]} themes - the themes, in data order
 * @param {string} sort - featured, az or color
 * @returns {object[]}
 */
export function order(themes, sort) {
  const sorted = [...themes];

  if (sort === 'az') {
    return sorted.sort((a, b) => a.name.localeCompare(b.name));
  }

  if (sort === 'color') {
    return sorted.sort((a, b) => rainbowRank(a.accent) - rainbowRank(b.accent));
  }

  return sorted;
}

/**
 * A hex color's red, green and blue, 0 up to 255.
 * @param {string} hex - `#rgb` or `#rrggbb`
 * @returns {number[]}
 */
function channels(hex) {
  const digits = hex.length === 4 ? hex.slice(1).replace(/./g, '$&$&') : hex.slice(1);

  return [0, 2, 4].map((at) => parseInt(digits.slice(at, at + 2), 16));
}

/**
 * The hue of a hex color in degrees, 0 for a gray.
 * @param {string} hex - `#rgb` or `#rrggbb`
 * @returns {number} 0 up to 360
 */
function hueOf(hex) {
  const [red, green, blue] = channels(hex);
  const top = Math.max(red, green, blue);
  const spread = top - Math.min(red, green, blue);

  if (!spread) {
    return 0;
  }

  if (top === red) {
    return (((green - blue) / spread + 6) % 6) * 60;
  }

  if (top === green) {
    return ((blue - red) / spread + 2) * 60;
  }

  return ((red - green) / spread + 4) * 60;
}

/**
 * A color's place in the rainbow: its hue turned 30 degrees, so the reds just
 * under 360 lead the oranges, and 360 for a grey, which closes the row.
 * @param {string} hex - `#rgb` or `#rrggbb`
 * @returns {number} 0 up to 360
 */
function rainbowRank(hex) {
  const levels = channels(hex);

  return Math.max(...levels) - Math.min(...levels) < MIN_CHROMA ? 360 : (hueOf(hex) + 30) % 360;
}

export default async () => {
  const $search = document.getElementById('explorer-search');
  const $grid = document.querySelector('[data-explorer-grid]');
  const $count = document.querySelector('[data-explorer-count]');
  const $empty = document.querySelector('[data-explorer-empty]');
  const $switch = document.querySelector('[data-explorer-switch]');
  const $sort = document.querySelector('[data-explorer-sort]');
  const $chips = document.querySelector('[data-explorer-chips]');
  const $track = document.querySelector('[data-explorer-chips-track]');
  const themes = JSON.parse(document.querySelector('[data-explorer-themes]').dataset.explorerThemes);
  const cards = new Map([...$grid.querySelectorAll('[data-theme-card]')].map(($card) => [$card.dataset.themeCard, $card]));
  const still = window.matchMedia('(prefers-reduced-motion: reduce)');
  let state = readState(window.location.search);

  const pressMode = bindPills($switch, (mode) => change('mode', mode));
  const pressSort = bindPills($sort, (sort) => change('sort', sort));
  const pressCategory = bindPills($track, (category) => change('category', category));

  const render = () => {
    const sorted = order(themes, state.sort);
    const shown = sorted.filter((theme) => matches(theme, state));

    $grid.append(...sorted.map((theme) => cards.get(theme.id)));
    for (const theme of sorted) {
      cards.get(theme.id).hidden = !shown.includes(theme);
    }

    $grid.dataset.mode = state.mode;
    $count.textContent = `${shown.length} ${shown.length === 1 ? 'theme' : 'themes'}`;
    $empty.hidden = shown.length > 0;
    pressMode(state.mode);
    pressSort(state.sort);
    pressCategory(state.category);

    if (document.activeElement !== $search) {
      $search.value = state.q;
    }
  };

  const change = (key, value) => {
    state = { ...state, [key]: value };
    window.history.replaceState(null, '', `${window.location.pathname}${writeState(state)}`);
    render();
  };

  // The fade and the arrow go once the track has nothing more to the right
  const syncEdge = () => {
    $chips.toggleAttribute('data-at-end', $track.scrollLeft + $track.clientWidth >= $track.scrollWidth - 2);
  };

  $search.form.addEventListener('submit', (event) => event.preventDefault());
  $search.addEventListener('input', () => change('q', $search.value));

  document.querySelector('[data-explorer-chips-more]').addEventListener('click', () => {
    $track.scrollBy({ left: $track.clientWidth * 0.75, behavior: still.matches ? 'auto' : 'smooth' });
  });
  $track.addEventListener('scroll', syncEdge, { passive: true });
  new ResizeObserver(syncEdge).observe($track);

  render();

  const $pressed = $track.querySelector('[aria-pressed="true"]');

  if ($pressed) {
    $track.scrollLeft = $pressed.offsetLeft - $track.clientWidth / 2;
  }
};
